<section class="container page-section"><p class="breadcrumb"><a href="/">หน้าแรก</a> / ติดต่อเรา</p><div class="page-heading"><p class="eyebrow">GET IN TOUCH</p><h1>ติดต่อกองประชาสัมพันธ์</h1><p><?= e(setting('university')) ?></p></div><div class="contact-grid"><div class="contact-card"><?php foreach(['address'=>['pin','ที่อยู่'],'phone'=>['phone','โทรศัพท์'],'email'=>['mail','อีเมล'],'hours'=>['clock','เวลาทำการ']] as $key=>[$ico,$label]): $value=setting($key); ?><div class="contact-item"><?= icon($ico,28) ?><div><h2><?= $label ?></h2><?php if($key==='email' && filter_var($value,FILTER_VALIDATE_EMAIL)): ?><a href="mailto:<?= e($value) ?>"><?= e($value) ?></a><?php elseif($key==='phone' && $value): ?><a href="tel:<?= e(preg_replace('/[^0-9+]/','',$value)) ?>"><?= e($value) ?></a><?php else: ?><p><?= nl2br(e($value?:'ข้อมูลรอยืนยันจากหน่วยงาน')) ?></p><?php endif ?></div></div><?php endforeach ?></div><div class="map-card contact-map"><?php $mapAddress=setting('address'); if($mapAddress): ?><iframe class="contact-map-frame" title="แผนที่มหาวิทยาลัยสวนดุสิต" src="https://www.google.com/maps?q=<?= e(rawurlencode(setting('university').' '.$mapAddress)) ?>&amp;output=embed" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe><?php endif ?><div class="contact-map-info"><h2>การเดินทาง</h2><p>มหาวิทยาลัยสวนดุสิต</p><?php if(safe_url(setting('map_url'))): ?><a class="button" href="<?= e(setting('map_url')) ?>" target="_blank" rel="noopener noreferrer">เปิดเส้นทางใน Google Maps ↗</a><?php elseif($mapAddress): ?><a class="button" href="https://www.google.com/maps/dir/?api=1&amp;destination=<?= e(rawurlencode(setting('university').' '.$mapAddress)) ?>" target="_blank" rel="noopener noreferrer">เปิดเส้นทางใน Google Maps ↗</a><?php else: ?><p class="muted">ลิงก์แผนที่รอยืนยัน</p><?php endif ?></div></div></div></section>
